using System.Security.Cryptography;using CustomerService.Application.Abstractions.Notifications;namespace CustomerService.Infrastructure.External.Notifications;public sealed class PinService:IPinService{public (string Hash,string Salt) Hash(string pin){var salt=RandomNumberGenerator.GetBytes(32);var hash=Rfc2898DeriveBytes.Pbkdf2(pin,salt,210000,HashAlgorithmName.SHA256,32);return(Convert.ToBase64String(hash),Convert.ToBase64String(salt));}public bool Verify(string pin,string hash,string salt)=>CryptographicOperations.FixedTimeEquals(Rfc2898DeriveBytes.Pbkdf2(pin,Convert.FromBase64String(salt),210000,HashAlgorithmName.SHA256,32),Convert.FromBase64String(hash));}